import { Visit } from './visit';
import { CheckInNotAllowedError, VisitAlreadyCheckedInError } from './visit.errors';
import { WaitingQueue } from './waiting-queue';

function expected(id = 'v-1'): Visit {
  return Visit.expect({
    id,
    appointmentId: `appt-${id}`,
    personId: 'person-1',
    practitionerId: 'dr-1',
    expectedAt: new Date('2026-03-02T10:00:00Z'),
  });
}

describe('Visit', () => {
  it('checks in an expected visitor and records the arrival time', () => {
    const visit = expected();
    const arrival = new Date('2026-03-02T09:50:00Z');

    visit.checkIn(arrival);

    expect(visit.status).toBe('CHECKED_IN');
    expect(visit.checkedInAt).toEqual(arrival);
  });

  it('refuses to check in a cancelled visit', () => {
    const visit = expected();
    visit.cancel();

    expect(() => visit.checkIn(new Date())).toThrow(CheckInNotAllowedError);
  });

  it('refuses a second check-in', () => {
    const visit = expected();
    visit.checkIn(new Date());

    expect(() => visit.checkIn(new Date())).toThrow(VisitAlreadyCheckedInError);
  });

  it('keeps a checked-in visit when the appointment is cancelled afterwards', () => {
    const visit = expected();
    visit.checkIn(new Date());

    visit.cancel();

    expect(visit.status).toBe('CHECKED_IN');
  });
});

describe('WaitingQueue', () => {
  it('orders checked-in visitors by arrival and ignores the others', () => {
    const late = expected('late');
    const early = expected('early');
    const notArrived = expected('absent');
    late.checkIn(new Date('2026-03-02T09:55:00Z'));
    early.checkIn(new Date('2026-03-02T09:40:00Z'));

    const queue = WaitingQueue.of([late, notArrived, early]);

    expect(queue.size).toBe(2);
    expect(queue.positionOf('early')).toBe(1);
    expect(queue.positionOf('late')).toBe(2);
    expect(queue.positionOf('absent')).toBeNull();
  });
});
import type { PersonId, PractitionerId } from '@/shared-kernel';
import { CheckInNotAllowedError, VisitAlreadyCheckedInError } from './visit.errors';

export type VisitStatus = 'EXPECTED' | 'CHECKED_IN' | 'CANCELLED';

export interface VisitSnapshot {
  id: string;
  appointmentId: string;
  personId: PersonId;
  practitionerId: PractitionerId;
  expectedAt: Date;
  status: VisitStatus;
  checkedInAt: Date | null;
}

export interface ExpectVisitInput {
  id: string;
  appointmentId: string;
  personId: PersonId;
  practitionerId: PractitionerId;
  expectedAt: Date;
}

export class Visit {
  private constructor(private props: VisitSnapshot) {}

  static expect(input: ExpectVisitInput): Visit {
    return new Visit({ ...input, status: 'EXPECTED', checkedInAt: null });
  }

  static restore(snapshot: VisitSnapshot): Visit {
    return new Visit({ ...snapshot });
  }

  get id(): string {
    return this.props.id;
  }

  get status(): VisitStatus {
    return this.props.status;
  }

  get checkedInAt(): Date | null {
    return this.props.checkedInAt;
  }

  checkIn(now: Date): void {
    if (this.props.status === 'CHECKED_IN') {
      throw new VisitAlreadyCheckedInError();
    }
    if (this.props.status !== 'EXPECTED') {
      throw new CheckInNotAllowedError(this.props.status);
    }
    this.props.status = 'CHECKED_IN';
    this.props.checkedInAt = now;
  }

  cancel(): void {
    if (this.props.status === 'EXPECTED') {
      this.props.status = 'CANCELLED';
    }
  }

  toSnapshot(): VisitSnapshot {
    return { ...this.props };
  }
}
import type { Visit } from './visit';

export class WaitingQueue {
  private constructor(private readonly visits: readonly Visit[]) {}

  static of(visits: readonly Visit[]): WaitingQueue {
    const waiting = visits
      .filter((visit) => visit.status === 'CHECKED_IN' && visit.checkedInAt !== null)
      .sort((a, b) => (a.checkedInAt as Date).getTime() - (b.checkedInAt as Date).getTime());
    return new WaitingQueue(waiting);
  }

  get size(): number {
    return this.visits.length;
  }

  positionOf(visitId: string): number | null {
    const index = this.visits.findIndex((visit) => visit.id === visitId);
    return index === -1 ? null : index + 1;
  }

  entries(): readonly Visit[] {
    return this.visits;
  }
}
import { Injectable } from '@nestjs/common';
import type { FrontDeskVisit } from '@prisma/client';
import { PrismaService } from '@/infrastructure/prisma/prisma.service';
import { Visit, VisitStatus } from '../domain/visit';
import { VisitRepository } from '../domain/visit.repository';

@Injectable()
export class PrismaVisitRepository extends VisitRepository {
  constructor(private readonly prisma: PrismaService) {
    super();
  }

  async findByAppointmentId(appointmentId: string): Promise<Visit | null> {
    const row = await this.prisma.frontDeskVisit.findUnique({ where: { appointmentId } });
    return row ? toDomain(row) : null;
  }

  async findCheckedIn(): Promise<Visit[]> {
    const rows = await this.prisma.frontDeskVisit.findMany({ where: { status: 'CHECKED_IN' } });
    return rows.map(toDomain);
  }

  async save(visit: Visit): Promise<void> {
    const { id, ...data } = visit.toSnapshot();
    await this.prisma.frontDeskVisit.upsert({ where: { id }, create: { id, ...data }, update: data });
  }
}

function toDomain(row: FrontDeskVisit): Visit {
  return Visit.restore({ ...row, status: row.status as VisitStatus });
}
